=== api/index ===
import HttpRequest from "@/request"
import { getToken, getTmpToken } from '@/utils/auth'
import store from '@/store'

function isInspect() {
  return process.env.VUE_APP_ENV == 'inspect'
}

const httpRequest = new HttpRequest({
  baseURL: process.env.VUE_APP_BASE_API,
  contentType: isInspect() ? 'application/x-www-form-urlencoded' : 'application/json;charset=utf-8',
  // 获取token方法
  getToken: () => {
    if (window.location.pathname.includes('/register/')) {
      return getTmpToken()
    }
    return getToken()
  },
  // 退出登录方法
  logout: () => {
    store.dispatch('LogOut').then(() => {
      window.location.href = '/index'
    })
  },
})

export default httpRequest.init()

